dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "pigean_gene",
      "header": "Connecting gene sets to phenotypes | Browse by gene",
      "data point": {
        "type": "bioindex",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/pigean-gene?q=$gene&limit=10000",
        "continue url": "https://cfde.hugeampkpnbi.org/api/bio/cont?limit=10000&token=",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "search parameters": [
        {
          "parameter": "gene",
          "label": "Gene",
          "type": "input",
          "values": "kp genes"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype_name"
          },
          {
            "type": "raw",
            "field name": "Phenotype ID",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Direct genetic support",
            "raw field": "log_bf"
          },
          {
            "type": "raw",
            "field name": "Direct genetic support",
            "raw field": "huge_score"
          },
          {
            "type": "raw",
            "field name": "Indirect genetic support",
            "raw field": "prior"
          },
          {
            "type": "raw",
            "field name": "Combined genetic support",
            "raw field": "combined"
          },
          {
            "type": "join multi",
            "field name": "CFDE gene sets",
            "fields to join": [
              "phenotype",
              "gene"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "All gene sets",
            "fields to join": [
              "phenotype",
              "gene"
            ],
            "join by": [
              ","
            ]
          }
        ],
        "top rows": [
          "Phenotype",
          "Phenotype ID",
          "Combined genetic support",
          "Direct genetic support",
          "Indirect genetic support",
          "CFDE gene sets",
          "All gene sets"
        ],
        "tool tips": {
          "Phenotype ID": "Phenotype identifier from the Association to Function Knowledge Portal. See the Searchable options page to map identifiers to descriptive terms.",
          "Combined genetic support": "A measure of the relevance of the gene to the phenotype, incorporating both direct support (from GWAS associations near the gene) and indirect support (membership in gene sets with genetic support). All measures of genetic support are in units of log-odds of probability. Consider the following thresholds for interpreting combined genetic support scores: 1-nominally significant, 2-strongly suggestive (i.e., indicative that a gene is in a locus but not yet genome-wide significant), and 3-very strong (>50% probability that a gene is involved in the phenotype; similar to nearest gene to a GWAS signal).",
          "Direct genetic support": "The component of genetic support as calculated from only the SNP associations nearby the gene. Thresholds for interpretation are the same as for combined genetic support.",
          "Indirect genetic support": "The component of genetic support as calculated from only the gene sets containing the gene. Intuitively, the prior probability that the gene is relevant to the trait before genetic data is observed. Thresholds for interpretation are the same as for combined genetic support.",
          "CFDE gene sets": "Gene sets derived from CFDE data that are associated with the phenotype.",
          "All gene sets": "Gene sets derived from CFDE data or from the Knowledge Center differential expression analysis that are associated with the phenotype."
        },
        "column formatting": {
          "Phenotype ID": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_gene_set_browser_phenotype?phenotype=",
            "new tab": "true"
          },
          "CFDE gene sets": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde.hugeampkpnbi.org/api/bio/",
                "index": "pigean-joined-gene",
                "parameters": [
                  "phenotype",
                  "gene"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "pre filters": [
                  {
                    "field": "Source",
                    "type": "filter out",
                    "values": [
                      "gene_set_list_msigdb_nohp",
                      "gene_set_list_mouse"
                    ]
                  }
                ],
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene set",
                    "raw field": "gene_set"
                  },
                  {
                    "type": "raw",
                    "field name": "Joint effect",
                    "raw field": "beta",
                    "if no value": "0"
                  },
                  {
                    "type": "raw",
                    "field name": "Marginal effect",
                    "raw field": "beta_uncorrected",
                    "if no value": "0"
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene set",
                  "Joint effect",
                  "Marginal effect",
                  "Source"
                ],
                "column formatting": {
                  "Gene set": {
                    "type": [
                      "kp phenotype link"
                    ],
                    "link to": "/r/kc_gene_set_browser_gene_set?geneSet=",
                    "new tab": "true"
                  },
                  "Source": {
                    "type": [
                      "kp phenotype link"
                    ],
                    "link to": "/r/kc_gene_set_browser_source?source=",
                    "new tab": "true"
                  }
                }
              },
              "visualizer": {
                "label": "",
                "type": "scatter plot",
                "star key": null,
                "render type": "single plot",
                "group by": "Phenotype",
                "color by": "Source",
                "y axis field": "Joint effect",
                "y axis label": "Joint effect",
                "x axis field": "Marginal effect",
                "x axis label": "Marginal effect",
                "ticks decimal point": "4",
                "render by": "Gene set",
                "hover content": [
                  "Joint effect",
                  "Marginal effect",
                  "Source"
                ],
                "height": 150,
                "width": 550,
                "plot margin": {
                  "left": 60,
                  "right": 20,
                  "top": 40,
                  "bottom": 50,
                  "bump": 5
                }
              }
            }
          },
          "All gene sets": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde.hugeampkpnbi.org/api/bio/",
                "index": "pigean-joined-gene",
                "parameters": [
                  "phenotype",
                  "gene"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene set",
                    "raw field": "gene_set"
                  },
                  {
                    "type": "raw",
                    "field name": "Joint effect",
                    "raw field": "beta",
                    "if no value": "0"
                  },
                  {
                    "type": "raw",
                    "field name": "Marginal effect",
                    "raw field": "beta_uncorrected",
                    "if no value": "0"
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene set",
                  "Joint effect",
                  "Marginal effect",
                  "Source"
                ],
                "column formatting": {
                  "Gene set": {
                    "type": [
                      "kp phenotype link"
                    ],
                    "link to": "/r/kc_gene_set_browser_gene_set?geneSet=",
                    "new tab": "true"
                  },
                  "Source": {
                    "type": [
                      "kp phenotype link"
                    ],
                    "link to": "/r/kc_gene_set_browser_source?source=",
                    "new tab": "true"
                  }
                }
              },
              "visualizer": {
                "label": "",
                "type": "scatter plot",
                "star key": null,
                "render type": "single plot",
                "group by": "Phenotype",
                "color by": "Source",
                "y axis field": "Joint effect",
                "y axis label": "Joint effect",
                "x axis field": "Marginal effect",
                "x axis label": "Marginal effect",
                "ticks decimal point": "4",
                "render by": "Gene set",
                "hover content": [
                  "Joint effect",
                  "Marginal effect",
                  "Source"
                ],
                "height": 150,
                "width": 550,
                "plot margin": {
                  "left": 60,
                  "right": 20,
                  "top": 40,
                  "bottom": 50,
                  "bump": 5
                }
              }
            }
          }
        }
      },
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "Combined genetic support",
            "type": "phewas plot",
            "group by": "phenotype group",
            "y axis field": "Combined genetic support",
            "convert y -log10": "false",
            "y ticks decimal point": "2",
            "phenotype map": "kp phenotype map",
            "render by": "Phenotype ID",
            "y axis label": "Combined genetic support",
            "x axis label": "",
            "beta field": null,
            "hover content": [
              "Phenotype",
              "Phenotype ID",
              "Combined genetic support",
              "Direct genetic support",
              "Indirect genetic support"
            ],
            "thresholds": [
              "2"
            ],
            "label in black": "greater than",
            "height": 400,
            "star key": "Phenotype",
            "plot margin": {
              "left": 120,
              "right": 120,
              "top": 250,
              "bottom": 150,
              "bump": 5
            }
          },
          {
            "label": "Direct genetic support vs. Indirect genetic support",
            "type": "scatter plot",
            "star key": null,
            "render type": "single plot",
            "group by": "Gene",
            "color by": "Gene",
            "y axis field": "Direct genetic support",
            "y axis label": "Direct genetic support",
            "x axis field": "Indirect genetic support",
            "x axis label": "Indirect genetic support",
            "ticks decimal point": "4",
            "render by": "Phenotype",
            "hover content": [
              "Phenotype",
              "Phenotype ID",
              "Combined genetic support",
              "Direct genetic support",
              "Indirect genetic support"
            ],
            "height": 200,
            "width": 550,
            "plot margin": {
              "left": 60,
              "right": 20,
              "top": 40,
              "bottom": 50,
              "bump": 5
            }
          }
        ]
      },
      "filter width": "md",
      "filters": [
        {
          "field": "Phenotype",
          "label": "Phenotype",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "Combined genetic support",
          "label": "Combined genetic support(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Direct genetic support ",
          "label": "Direct genetic support(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Indirect genetic support",
          "label": "Indirect genetic support(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ]
    }
  ]
}

pageStyle:
.text-align-center{
   text-align:center;
}
.fixed-header {
 position: relative !important;
}
.multi-section-card {
margin-bottom: 20px;
}
#rp_tabs_contents { 
/* background: none !important;
  border: none; */ }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
    width: 830px !important;
    margin-left: 0 !important;
}

.byor-single-search-results-wrapper {
    width: 830px !important;
margin-left: 0 !important;
}

span.Tclin > strong {
padding: 0 10px;
    border: solid 2px #337ab7;
    border-radius: 5px;
}
span.Tchem > strong {
padding: 0 10px;
    border: solid 2px #5bc0de;
    border-radius: 5px;
}
span.Tbio > strong {
padding: 0 10px;
    border: solid 2px #ffb259;
    border-radius: 5px;
}
span.Tdark > strong {
padding: 0 10px;
    border: solid 2px #d32f2f;
    border-radius: 5px;
}

.info-card-row {
    margin-bottom: 15px;
}

.info-card-row > .row-key {
    width: 150px; display: inline-block; vertical-align: top;
}

.info-card-row > .row-value {
    width: calc(100% - 150px);  display: inline-block;
}

#byor_single_search { border-color: #ff7f00; }

.volcano-plot-content {
text-align: center;
}


.multi-page-search-wrapper { /*display: none;*/}

.multi-page-search-wrapper.in-section-ui { display: block;}



/* alex css begin */

.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.context-btns-wrapper {
  display: flex;
  gap: 10px;
}
.context-btns-wrapper .btn {
  text-wrap: nowrap;
  background: white;
  color: black;
  border: 1px solid #ccc;
}
.context-btns-wrapper .btn.active {
  background: #ff802c !important;
  border: 1px solid #ccc !important;
}
.context-btns-wrapper .btn.btn-warning {
  background: #ccc;
}
.context-btns-wrapper .btn.btn-warning:hover {
  background: #bbb;
}

.dataset-page-header {
  background: none;
  border: 0;
  display: none;
}

.kp-tabs-contents:has(.multi-page-search-wrapper) {
  /* background: none;
  border: none; */
}

.col-md-12:has(.multi-page-search-wrapper) {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.col-md-12{
  height: fit-content;
}

.tab-ui-wrapper {
  margin: 0;
  background: none;
  border-bottom: 0;
  padding: 0;
}
.tab-content-group {
  background: white;
  border-radius: 0 10px 10px 10px;
  border: 1px solid #ddd;
  padding: 10px 20px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
}

button.show-hide-section, button.capture-data {
  display: none;
}

.tab-content-group:has(.multi-section) {
  padding: 10px 0;
}

.multi-section {
  background: white;
  padding: 10px 20px 30px 20px;
  border-radius: 10px;
  border-bottom: 0;
}

.multi-section .section-header {
  padding: 10px 5px;
}
.multi-section .section-header h4 {
  font-size: 22px;
}
.section-header h4 small {
  font-size: 22px !important;
  padding-left: 10px;
    border-left: solid 1px #dddddd;
    margin-left: 5px;
}

.table-total-rows {
  padding-top: 3px;
}
.table-ui-wrapper {
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
  color: #5a5a5a;
  background: #ddd;
}
.tab-ui-wrapper .tab-ui-tab:hover {
  color: black;
}
.table-ui-wrapper .number-per-page {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}
.convert-2-csv {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}

/* tables */
.mbm-plot-content {
  margin: 0 0 20px 0;
}
.research-data-table-wrapper {
  margin: 0 15px;
}
table.research-data-table {
  border: 0 !important;
  text-align: left;
}
.research-data-table tbody:nth-child(odd) {
  background: #f9f9f9;
}

#section_IDG_gene .research-data-table td {
  border: 0 !important;
  padding: 10px 10px;
  vertical-align: top !important;
}

#section_IDG_gene .egl-table-page-ui-wrapper, #section_IDG_gene .table-total-rows, #section_IDG_gene .table-ui-wrapper {
  display: none;
}

#section_IDG_gene .table-wrapper { margin-top: 25px; }

th.Visit.Pharos { width: 120px !important; }

.research-data-table td {
  border: 0 !important;
  padding: 3px 10px;
  line-height: 1.5em;
}
.research-data-table > thead > tr > th {
  border: 0 !important;
  padding: 5px 10px;
}
.research-data-table > thead > tr > th.sortable-th {
  color: black;
}
[class*="cell-weight"] {
  padding-left: 10px;
}
.sortable-th:after {
  content: '';
  background: none;
  width: 10px;
  height: 10px;
  position: absolute;
  margin: 0 0 0 5px;
  bottom: 7px;
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
  border-top: 5px solid #b4b4b4;
  border-bottom: 5px solid transparent;
}
table.feature-table {
  border-bottom: 3px solid #cccccc;
}
.feature-table > tr > th.feature-title-th {
  background-color: #cccccc !important;
}
table.feature-table tr:nth-child(odd) {
  background: white;
}
table.feature-table th.feature-th-0 {
  background-color: #eeeeee !important;
  border-left: 0 !important;
  padding: 0.3rem 10px;
  border-bottom: 1px solid #ccc !important;
}

#section_general_gene_info_function .row-value.Function {
  font-size: 16px;
  line-height: 26px;
}

/* colors */  
table a {
  color: #ff6600 !important;
}
.show-evidence-btn {
  background: #ffa02c !important;
  border: 0;
}
.show-evidence-btn:hover {
  background: #dc5800 !important;
  color:white !important;
}
.tab-ui-wrapper .tab-ui-tab.loading > .flag {
  color: #ffaa2c;
}
.page-item.active .page-link {
  background-color: #ffa02c;
}
.page-link {
  color: #ff6600;
}

img.dcc-logo {
  width: 100px;
  height: 100px;
  object-fit: contain;
  margin-top: -15px;
}

/* page descriptions */
.page-description-content {
  /* padding-left: 175px; */
  margin: 10px;
  min-height: 70px;
}
.page-description-content h4 {
  font-size: 16px;
  font-weight: bold;
}
.page-description-content p {
  font-size: 14px;
  line-height: normal;
  margin: 0;
  margin-bottom: 8px;
}

/* filters, search blocks */
.multi-page-search-wrapper {
  height: fit-content;
}
div.filtering-ui-wrapper {
  border: 0;
  border-radius: 0;
  border-left: 3px solid #ff6600;
  margin: 0;
}
.filtering-ui-wrapper>h4.card-title {
  color: #ff6600;
}
.filtering-ui-wrapper.search-criteria {
  /*border: 0;
  background: #efefef;*/
  border-left: 3px solid #34679a;
}
.filtering-ui-wrapper.search-criteria>h4.card-title {
  color: #34679a;
}
.search-fields-wrapper .search-field:empty {
  display: none;
}
.filtering-ui-content .btn-primary {
  background: #ff7f00;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #dc5800;
}
.filtering-ui-content .btn-warning {
  background: #ccc;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #bbb;
}

.research-data-table td {
overflow-wrap: anywhere;
}

/*center search bar with wrapper*/
.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
}
/*dont make search bar take up whole wrapper */
.byor-single-search-wrapper{
width:fit-content !important;
}
/* hode context buttons */
.context-btns-wrapper {
  display: none;
  gap: 10px;
}

/*set SS link colors */
a.ss-explore {
color: #007bff !important;
}

.required-parameters-label {
display: none !important;
}

.required-parameter {
  border: none !important;
  margin-left: 10px !important;
}
